      ],
      package: 'taro_ui',
      fontSize: 16,
      fontWeight: FontWeight.w400,
      height: 24 / 16,
      letterSpacing: 0,
      leadingDistribution: TextLeadingDistribution.even,
    ),
    label: TextStyle(
      fontFamily: 'IBM Plex Sans',
      fontFamilyFallback: <String>[
        'IBM Plex Sans Arabic',
        'IBM Plex Sans JP',
        'IBM Plex Sans KR',
      ],
      package: 'taro_ui',
      fontSize: 15,
      fontWeight: FontWeight.w500,
      height: 20 / 15,
      letterSpacing: 0.1,
      leadingDistribution: TextLeadingDistribution.even,
    ),
    caption: TextStyle(
      fontFamily: 'IBM Plex Sans',
      fontFamilyFallback: <String>[
        'IBM Plex Sans Arabic',
        'IBM Plex Sans JP',
        'IBM Plex Sans KR',
      ],
      package: 'taro_ui',
      fontSize: 13,
      fontWeight: FontWeight.w400,
      height: 18 / 13,
      letterSpacing: 0.2,
      leadingDistribution: TextLeadingDistribution.even,
    ),
    numeral: TextStyle(
      fontFamily: 'IM Fell English SC',
      package: 'taro_ui',
      fontSize: 20,
      fontWeight: FontWeight.w400,
      height: 24 / 20,
      letterSpacing: 1,
      leadingDistribution: TextLeadingDistribution.even,
    ),
  );

  /// The `dark` mode.
  static const TaroTypeTokens dark = light;

  /// One per screen at most: onboarding titles, the Today greeting.
  final TextStyle display;

  /// Screen titles, the reading title.
  final TextStyle headline;

  /// Card names on revealed cards and card detail.
  final TextStyle cardName;

  /// Long-form AI and authored reading text. Line height ≥ 1.5, measure ≤ 70 characters via layout-readingMaxWidth.
  final TextStyle bodyReading;

  /// Section headings, sheet titles, reading section headings.
  final TextStyle title;

  /// List-row titles, card-position titles, pack names.
  final TextStyle titleSmall;

  /// All UI copy. Minimum body size is 16px.
  final TextStyle body;

  /// Buttons, chips, tabs.
  final TextStyle label;

  /// Captions, disclaimers under readings, timestamps. Minimum 12px.
  final TextStyle caption;

  /// Roman numerals on card faces. Latin letters in every locale, so one face serves all 12.
  final TextStyle numeral;

  /// Interpolates between [a] and [b] (theme animations).
  static TaroTypeTokens lerp(TaroTypeTokens a, TaroTypeTokens b, double t) =>
      TaroTypeTokens(
        display: TextStyle.lerp(a.display, b.display, t)!,
        headline: TextStyle.lerp(a.headline, b.headline, t)!,
        cardName: TextStyle.lerp(a.cardName, b.cardName, t)!,
        bodyReading: TextStyle.lerp(a.bodyReading, b.bodyReading, t)!,
        title: TextStyle.lerp(a.title, b.title, t)!,
        titleSmall: TextStyle.lerp(a.titleSmall, b.titleSmall, t)!,
        body: TextStyle.lerp(a.body, b.body, t)!,
        label: TextStyle.lerp(a.label, b.label, t)!,
        caption: TextStyle.lerp(a.caption, b.caption, t)!,
        numeral: TextStyle.lerp(a.numeral, b.numeral, t)!,
      );
}
